 "content": "from collections import Counter

def transform(grid):
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    first = next((i for i, row in enumerate(grid) if any(v != background for v in row)), len(grid))
    out = [row[:] for row in grid]
    if first < len(grid):
        for i in range(len(grid) - 1, first, -1):
            out[i] = grid[i - 1][:]
        out[first] = [background] * len(grid[first])
    return out
